sys_script.script:
/**
 * Business Rule: Process ACH Transfer & Webhook
 * Table:         x_274351_finance_0_txn (Transactions)
 * When:          Before Insert
 * Order:         (default)
 *
 * Handles transactions of type 'ach_transfer'. Generates a unique ACH
 * transaction number (ACH-XXXXXX), validates that the transfer amount is
 * a positive number, and optionally sends a JSON payload to an external
 * webhook endpoint via RESTMessageV2 when a webhook_key is provided on
 * the transaction record.
 *
 * Note: Deposit and withdrawal transaction numbers are generated by the
 * separate "Set Transaction Details" business rule.
 */
(function executeRule(current, previous /*null when async*/) {
    var txnType = current.getValue('type');

    // Only process ACH transfers — other types are handled elsewhere
    if (txnType === 'ach_transfer') {
        // 1. Generate a unique ACH transaction number using epoch timestamp suffix
        var txnNum = 'ACH-' + new Date().getTime().toString().slice(-6);
        current.setValue('number', txnNum);

        // 2. Validate that the transfer amount is a positive number
        var amount = parseFloat(current.getValue('amount'));
        if (isNaN(amount) || amount <= 0) {
            gs.addErrorMessage('A valid transfer amount greater than zero is required.');
            current.setAbortAction(true);
            return;
        }

        // 3. If a webhook key is provided, send the transfer details to the external endpoint
        var webhookKey = current.getValue('webhook_key');
        if (webhookKey) {
            try {
                // Build the outbound REST request
                var rm = new sn_ws.RESTMessageV2();
                rm.setEndpoint('https://webhook.site/' + webhookKey);
                rm.setHttpMethod('POST');
                rm.setRequestHeader('Content-Type', 'application/json');

                // Assemble the webhook payload with transaction details
                var payload = {
                    transaction: txnNum,
                    amount: amount,
                    account: current.getDisplayValue('account'),
                    description: current.getValue('description'),
                    timestamp: new GlideDateTime().getDisplayValue()
                };

                rm.setRequestBody(JSON.stringify(payload));
                var response = rm.execute();

                // Provide user feedback based on the webhook response status
                if (response.getStatusCode() === 200) {
                    gs.addInfoMessage('ACH Transfer ' + txnNum + ' created and webhook sent successfully.');
                } else {
                    gs.addWarningMessage('ACH Transfer created, but webhook returned status: ' + response.getStatusCode());
                }
            } catch (e) {
                // Log the error server-side and notify the user gracefully
                gs.error('ACH Webhook Integration Error: ' + e.message);
                gs.addErrorMessage('Transfer recorded, but webhook transmission failed.');
            }
        } else {
            gs.addInfoMessage('ACH Transfer ' + txnNum + ' successfully created.');
        }
    }

})(current, previous);
